*/



//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//
scwin.vScrenID = 'ULDMGT80400.gfm';

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.MxDataSet_OnLoadCompleted = function(e) {
    textbox_1.setValue("총 " + rowcount + "건");
};

scwin.btn_cal_onclick = function(e) {

    //----W-Craft WebSquare 변환 확인: popUpCalendar----//
    popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); //alert('image_2.onclick');

};

scwin.btn_sys_search_onclick = function(e) {
    if (txb_date.Text !== "") {
        scwin.listSync(); //alert();

    } else {
        alert("기준일자를 지정하십시요");
    }
};

scwin.btn_toExcel_onclick = function(e) {
    $c.data.downloadGridViewExcel(grid01, "기업개황", "", "8");
};

// 일반 함수
scwin.listSync = function() {
    //var url = "/dartif.do?method=searchDartIF&inputMessageId=job_dartif&outputMessageId=job_dartif&RCV_DDTM="+txb_date.Text; 
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/todayssend.do",
        ref : "",
        target : "MxDataSet=body.content",
        submitDoneHandler : scwin.MxDataSet_OnLoadCompleted,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


};

scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox_01(panel_1);
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        submitDoneHandler : scwin.MxDataSet_OnLoadCompleted,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);



    //----W-Craft WebSquare 변환 확인: toDaySet----//
    toDaySet(txb_date);
};
